def finalDominoes(dominoes):
    s = 'L' + dominoes + 'R'
    out = list(s)
    prev = 0
    for i in range(1, len(s)):
        if s[i] == '.':
            continue
        a, b = s[prev], s[i]
        if a == b:
            for k in range(prev + 1, i):
                out[k] = a
        elif a == 'R' and b == 'L':
            lo, hi = prev + 1, i - 1
            while lo < hi:
                out[lo] = 'R'
                out[hi] = 'L'
                lo += 1
                hi -= 1
        prev = i
    return ''.join(out[1:-1])
